WITH parsed AS (SELECT id, plan, effective_from, tier_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price FROM price_tiers) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, APPROX_PERCENTILE(entry_price, 0.5) AS entry_price_p50, MAX(avg_tier_price) FILTER (WHERE plan = 'starter') AS starter_max_avg_tier_price FROM parsed GROUP BY 1;
